#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Fill an HWPX (HWPML) template with values from JSON.

- Reads /root/project_proposal.json
- Reads /root/project_proposal_template.hwpx (zip)
- Replaces {{...}} placeholders in all XML files
- Normalizes budget formatting (remove commas, keep currency symbol)
- For phase lines (단계1/2/3), appends month span like " (N개월)"
- Removes layout-cache elements (lineSegArray / lineSeg etc.) from modified paragraphs
- Writes /root/project_proposal_ready.hwpx

This script is intentionally conservative: if any placeholders remain after processing,
it fails with a clear error so the output package is not silently incomplete.
"""

from __future__ import annotations

import json
import re
import sys
import zipfile
from dataclasses import dataclass
from datetime import date
from pathlib import Path
import xml.etree.ElementTree as ET

JSON_PATH = Path("/root/project_proposal.json")
TEMPLATE_PATH = Path("/root/project_proposal_template.hwpx")
OUTPUT_PATH = Path("/root/project_proposal_ready.hwpx")

PLACEHOLDER_RE = re.compile(r"\{\{\s*([^}]+?)\s*\}\}")

# We remove these from modified <hp:p> elements.
# HWPML templates often include them as cached layout; when text changes they can become stale.
LINESEG_LOCALNAMES = {
    "lineSegArray",
    "lineSeg",
    "linesegarray",
    "lineseg",
    "lineSegarray",
}


def localname(tag: str) -> str:
    """Return XML localname for either '{ns}tag' or 'prefix:tag'."""
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    if ":" in tag:
        return tag.split(":", 1)[1]
    return tag


def normalize_budget(value: str) -> str:
    """Remove commas from a currency string, preserving a leading symbol if present."""
    if value is None:
        return value
    s = str(value)
    if not s:
        return s

    # Keep a leading non-digit/non-space char like ₩, $, €.
    m = re.match(r"^\s*([^0-9\s])\s*(.*)$", s)
    if m:
        sym = m.group(1)
        rest = m.group(2)
        rest = rest.replace(",", "")
        return f"{sym}{rest}"

    return s.replace(",", "")


@dataclass(frozen=True)
class MonthSpan:
    start_ym: tuple[int, int]
    end_ym: tuple[int, int]
    months_inclusive: int


def parse_year_month(s: str) -> tuple[int, int] | None:
    """Parse YYYY-MM or YYYY.MM or YYYY-MM-DD or YYYY.MM.DD; returns (year, month)."""
    s = s.strip()
    m = re.match(r"^(\d{4})[\.-](\d{1,2})(?:[\.-](\d{1,2}))?$", s)
    if not m:
        return None
    y = int(m.group(1))
    mo = int(m.group(2))
    if not (1 <= mo <= 12):
        return None
    return (y, mo)


def compute_month_span(text: str) -> MonthSpan | None:
    """Find a date or date range in text and compute inclusive month span."""
    # Look for a range first: 2026-08 ~ 2026-10 (or with dots)
    range_m = re.search(
        r"(\d{4}[\.-]\d{1,2}(?:[\.-]\d{1,2})?)\s*(?:~|–|-|to)\s*(\d{4}[\.-]\d{1,2}(?:[\.-]\d{1,2})?)",
        text,
    )
    if range_m:
        s1, s2 = range_m.group(1), range_m.group(2)
        ym1 = parse_year_month(s1)
        ym2 = parse_year_month(s2)
        if not ym1 or not ym2:
            return None
        start_idx = ym1[0] * 12 + (ym1[1] - 1)
        end_idx = ym2[0] * 12 + (ym2[1] - 1)
        if end_idx < start_idx:
            return None
        months = (end_idx - start_idx) + 1
        return MonthSpan(start_ym=ym1, end_ym=ym2, months_inclusive=months)

    # Otherwise, look for a single year-month or year-month-day.
    single_m = re.search(r"(\d{4}[\.-]\d{1,2}(?:[\.-]\d{1,2})?)", text)
    if single_m:
        ym = parse_year_month(single_m.group(1))
        if not ym:
            return None
        return MonthSpan(start_ym=ym, end_ym=ym, months_inclusive=1)

    return None


