    # Catch both "1단계" and "단계1" variants.
    return bool(re.search(r"(?:\b[123]\s*단계\b|단계\s*[123])", text))


def replace_placeholders_in_text(text: str, values: dict[str, object]) -> tuple[str, set[str]]:
    """Replace all {{key}} placeholders using values dict.

    Returns (new_text, used_keys)
    """

    used: set[str] = set()

    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key not in values:
            # Leave placeholder in place; we'll error later with a full scan.
            return m.group(0)
        used.add(key)
        v = values[key]
        if key in {"예산", "budget", "총예산"}:
            return normalize_budget(str(v))
        return str(v)

    return PLACEHOLDER_RE.sub(repl, text), used


def remove_lineseg_cache_from_paragraph(p: ET.Element) -> int:
    """Remove lineSegArray/lineSeg nodes inside <hp:p>. Returns count removed."""
    removed = 0

    # ElementTree doesn't provide parent pointers; iterate parents and prune children.
    for parent in list(p.iter()):
        for child in list(parent):
            if localname(child.tag) in LINESEG_LOCALNAMES:
                parent.remove(child)
                removed += 1

    return removed


