    return "".join((t.text or "") for t in t_nodes)


def set_paragraph_text(t_nodes: list[ET.Element], new_text: str) -> None:
    if not t_nodes:
        return
    if len(t_nodes) == 1:
        t_nodes[0].text = new_text
        return

    # Preserve structure but force full paragraph string into the first node;
    # clear the rest so we don't duplicate content.
    t_nodes[0].text = new_text
    for t in t_nodes[1:]:
        t.text = ""


def process_section_xml(xml_bytes: bytes, values: dict[str, object], file_name: str) -> tuple[bytes, dict[str, int]]:
    """Return (new_xml_bytes, stats)."""
    stats = {
        "paragraphs_modified": 0,
        "lineseg_removed": 0,
        "placeholders_replaced": 0,
        "phase_spans_appended": 0,
    }

    try:
        root = ET.fromstring(xml_bytes)
    except ET.ParseError as e:
        raise RuntimeError(f"Failed to parse XML {file_name}: {e}")

