            continue

        # Collect all <hp:t> nodes under this paragraph.
        t_nodes = [el for el in p.iter() if localname(el.tag) == "t"]
        if not t_nodes:
            continue

        original_full = paragraph_text(t_nodes)
        used_keys: set[str] = set()

        # First pass: replace placeholders per text node.
        changed_any = False
        for t in t_nodes:
            orig = t.text or ""
            new, used = replace_placeholders_in_text(orig, values)
            used_keys |= used
            if new != orig:
                t.text = new
                changed_any = True

        # Second pass (robust): if placeholders still exist in the paragraph (possibly split),
        # do replacement on the concatenated text and rewrite into the first <hp:t>.
        full_after_nodewise = paragraph_text(t_nodes)
        if "{{" in full_after_nodewise and "}}" in full_after_nodewise:
            replaced_full, used2 = replace_placeholders_in_text(full_after_nodewise, values)
            used_keys |= used2
            if replaced_full != full_after_nodewise:
                set_paragraph_text(t_nodes, replaced_full)
                changed_any = True

        # Phase month span append, after placeholder replacement.
        full_after_repl = paragraph_text(t_nodes)
        if is_phase_line(full_after_repl) and not re.search(r"\(\s*\d+\s*개월\s*\)", full_after_repl):
            span = compute_month_span(full_after_repl)
            if span:
                set_paragraph_text(t_nodes, full_after_repl + f" ({span.months_inclusive}개월)")
                stats["phase_spans_appended"] += 1
                changed_any = True

        if changed_any:
            stats["paragraphs_modified"] += 1
            # Count replacements approximately: number of used keys in this paragraph.
            stats["placeholders_replaced"] += len(used_keys)
            stats["lineseg_removed"] += remove_lineseg_cache_from_paragraph(p)

    new_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return new_bytes, stats


def scan_for_placeholders_in_zip(zip_path: Path) -> list[tuple[str, str]]:
    """Return list of (filename, snippet) for any XML file containing {{...}}."""
    hits: list[tuple[str, str]] = []
    with zipfile.ZipFile(zip_path) as zf:
        for name in zf.namelist():
            if not name.lower().endswith(".xml"):
                continue
            txt = zf.read(name).decode("utf-8", errors="replace")
            if "{{" in txt or "}}" in txt:
                # Keep a small snippet for debugging.
                idx = txt.find("{{")
                snippet = txt[max(0, idx - 60) : idx + 120]
                hits.append((name, snippet))
    return hits


def main() -> int:
    if not JSON_PATH.exists():
        print(f"ERROR: missing JSON: {JSON_PATH}", file=sys.stderr)
        return 2
    if not TEMPLATE_PATH.exists():
        print(f"ERROR: missing template: {TEMPLATE_PATH}", file=sys.stderr)
        return 2
    if not zipfile.is_zipfile(TEMPLATE_PATH):
        print(f"ERROR: template is not a valid zip: {TEMPLATE_PATH}", file=sys.stderr)
        return 2

    values = json.loads(JSON_PATH.read_text(encoding="utf-8"))
    if not isinstance(values, dict):
        print("ERROR: JSON root must be an object", file=sys.stderr)
        return 2

    # Normalize budget value in the value map too (so even non-{{예산}} uses get normalized).
    if "예산" in values:
        values["예산"] = normalize_budget(str(values["예산"]))

    # Write output zip.
    total_stats = {"paragraphs_modified": 0, "lineseg_removed": 0, "placeholders_replaced": 0, "phase_spans_appended": 0}

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin, zipfile.ZipFile(
        OUTPUT_PATH, "w", compression=zipfile.ZIP_DEFLATED
    ) as zout:
        for name in zin.namelist():
            data = zin.read(name)
            if name.lower().endswith(".xml"):
                new_data, st = process_section_xml(data, values, name)
                for k in total_stats:
                    total_stats[k] += st.get(k, 0)
                zout.writestr(name, new_data)
            else:
                zout.writestr(name, data)

    # Verification: no placeholders should remain.
    hits = scan_for_placeholders_in_zip(OUTPUT_PATH)
    if hits:
        print("ERROR: Placeholders remain in output:", file=sys.stderr)
        for fn, snip in hits:
            print(f"- {fn}: ...{snip}...", file=sys.stderr)
        return 3

    print("OK: wrote", str(OUTPUT_PATH))
    print("Stats:")
    for k, v in total_stats.items():
        print(f"  {k}: {v}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

